-- FALAFEL BATACHANA — PARCEL MODULE — parcel_05_rollback.sql (GATE S4-PARCEL-30B)
-- EMERGENCY / COMPATIBILITY SCRIPT — never run without separate explicit approval.
--
-- PRIMARY ROLLBACK PLAN IS THE APPLICATION, NOT THIS SCRIPT: roll the app back (Vercel Instant Rollback) and keep the
-- additive Migration 05 schema. The pre-30B application never sends recipient_name and never selects the column, so it
-- runs unchanged on the Migration 05 database. Nothing in the database needs to be undone.
--
-- This script exists only for the rare case where the previous create_order_with_parcel body itself must be restored.
-- It is NON-DESTRUCTIVE:
--   * restores ONLY the function body to the exact pre-05 Production source (md5 7d491c097bf60b7e17beae25890b1238,
--     length 2474, CRLF — embedded below as hex so the bytes are exact);
--   * KEEPS the recipient_name column, its CHECK constraint and every stored recipient name (no DROP, no UPDATE);
--   * keeps the signature, SECURITY INVOKER, search_path '' and the service_role-only EXECUTE grant.
-- PREREQUISITE: the application must already be rolled back. With the old body restored, any request that still sends
-- p_parcel.recipient_name is rejected ('create_order_with_parcel: unexpected parcel field' → HTTP 400 invalid_parcel).
-- New parcels created after this rollback get recipient_name NULL; the kitchen falls back to the order's customer name.

BEGIN;

SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '60s';

DO $parcel_05_rollback$
DECLARE
  v_count integer;
  v_md5   text;
  v_len   integer;
  v_cfg   text[];
  v_oid   oid;
  v_src   text := convert_from(decode('', 'hex'), 'UTF8');
BEGIN
  IF md5(v_src) IS DISTINCT FROM '7d491c097bf60b7e17beae25890b1238' OR length(v_src) IS DISTINCT FROM 2474 THEN
    RAISE EXCEPTION 'parcel_05_rollback: embedded source is corrupt (md5 %, length %)', md5(v_src), length(v_src);
  END IF;

  SELECT count(*) INTO v_count
    FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
   WHERE n.nspname = 'public' AND p.proname = 'create_order_with_parcel';
  IF v_count <> 1 THEN
    RAISE EXCEPTION 'parcel_05_rollback: expected exactly one public.create_order_with_parcel, found %', v_count;
  END IF;
  SELECT md5(p.prosrc), length(p.prosrc) INTO v_md5, v_len
    FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
   WHERE n.nspname = 'public' AND p.proname = 'create_order_with_parcel'
     AND pg_get_function_identity_arguments(p.oid) = 'p_order jsonb, p_items jsonb, p_delivery jsonb, p_parcel jsonb';
  -- Only the reviewed Migration 05 body may be replaced (LF or CRLF install).
  IF NOT ((v_md5 = 'afbe93d74b201d6bd898edd2b6e28a63' AND v_len = 2656)
       OR (v_md5 = '6ceb72f6c80929adddd7a2b7bb1a0616' AND v_len = 2771)) THEN
    RAISE EXCEPTION 'parcel_05_rollback: installed create_order_with_parcel is not the parcel_05 version (md5 %, length %) — refusing', v_md5, v_len;
  END IF;

  EXECUTE format(
    'CREATE OR REPLACE FUNCTION public.create_order_with_parcel(p_order jsonb, p_items jsonb, p_delivery jsonb, p_parcel jsonb) '
    'RETURNS TABLE(created_order_id uuid, created_order_number integer, created_daily_number integer) '
    'LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path = %L AS %L', '', v_src);
  REVOKE ALL ON FUNCTION public.create_order_with_parcel(jsonb, jsonb, jsonb, jsonb) FROM PUBLIC, anon, authenticated;
  GRANT EXECUTE ON FUNCTION public.create_order_with_parcel(jsonb, jsonb, jsonb, jsonb) TO service_role;

  -- Post-check in the same transaction.
  SELECT p.oid, md5(p.prosrc), length(p.prosrc), p.proconfig INTO v_oid, v_md5, v_len, v_cfg
    FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
   WHERE n.nspname = 'public' AND p.proname = 'create_order_with_parcel';
  IF v_md5 IS DISTINCT FROM '7d491c097bf60b7e17beae25890b1238' OR v_len IS DISTINCT FROM 2474
     OR v_cfg IS DISTINCT FROM ARRAY['search_path=""']
     OR NOT has_function_privilege('service_role', v_oid, 'EXECUTE')
     OR has_function_privilege('anon', v_oid, 'EXECUTE')
     OR has_function_privilege('authenticated', v_oid, 'EXECUTE') THEN
    RAISE EXCEPTION 'parcel_05_rollback: post-check failed (md5 %, length %, config %)', v_md5, v_len, v_cfg;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = 'public.parcel_requests'::regclass
                  AND attname = 'recipient_name' AND NOT attisdropped) THEN
    RAISE EXCEPTION 'parcel_05_rollback: recipient_name column unexpectedly missing (this script never drops it)';
  END IF;
END
$parcel_05_rollback$;

COMMIT;
